brand.ts.content:
/*
 * bambiui logo artwork (576 x 560 units). Single source for the header mark
 * (icons.tsx), app/icon.svg and the generated app icons and social images.
 */

// bambiui mark: head silhouette, face (inner curve closed along the head edge) and eye.
export const brand = {
  head: "M0 490.342V100.342C0 45.342 7 8.342 30 1.342C65-9.358 148 45.342 189 115.342C219 111.342 253 109.342 287.5 109.342C322 109.342 356 111.342 386 115.342C427 45.342 510-9.358 545 1.342C568 8.342 575 45.342 575 100.342V490.342C575 533.342 548 559.342 505 559.342H70C27 559.342 0 533.342 0 490.342Z",
  faceCurve:
    "M0 355.842C3.996 322.842 110.517 372.342 169.451 389.342C219.895 397.842 244.867 395.842 259.851 334.842C273.835 278.842 199.418 208.342 246.366 137.842C263 118.842 290.317 116.994 310.794 137.842C340.261 167.842 356.743 228.842 394.701 266.842C432.658 304.842 575 381.605 575 410.842",
  face: "M246.366 137.842C263 118.842 290.317 116.994 310.794 137.842C340.261 167.842 356.743 228.842 394.701 266.842C432.658 304.842 575 381.605 575 410.842C575 425.842 575.624 453.347 575 489.842C574 548.342 532.5 559.342 502.581 559.342C502.581 559.342 127 560.342 70 559.342C13 558.342 0 518.842 0 490.342C0 461.842 0 355.842 0 355.842C3.996 322.842 110.517 372.342 169.451 389.342C219.895 397.842 244.867 395.842 259.851 334.842C273.835 278.842 199.418 208.342 246.366 137.842Z",
  eye: "M392.5 425.842A20 20 0 1 0 392.5 385.842A20 20 0 1 0 392.5 425.842Z",
};

export const brandColor = "#e8673c";

/**
 * Standalone SVG markup of the mark: the outline plus the filled upper head
 * (head minus face, via evenodd) and eye. `strokeWidth` is in artwork units.
 */
export function brandSvg({
  color = brandColor,
  strokeWidth = 22,
}: { color?: string; strokeWidth?: number } = {}) {
  const pad = strokeWidth;
  return [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${-pad} ${-pad} ${576 + pad * 2} ${560 + pad * 2}" fill="none" stroke="${color}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round">`,
    `<path d="${brand.head} ${brand.face} ${brand.eye}" fill="${color}" fill-rule="evenodd" stroke="none"/>`,
    ...[brand.head, brand.faceCurve, brand.eye].map((d) => `<path d="${d}"/>`),
    "</svg>",
  ].join("");
}

export const brandSvgDataUri = (options?: Parameters<typeof brandSvg>[0]) =>
  `data:image/svg+xml;base64,${btoa(Array.from(new TextEncoder().encode(brandSvg(options)), byte => String.fromCharCode(byte)).join(""))}`;

components/appearance.ts.content:
import type { CSSProperties } from "react";

/** Local instance values, not shared design-system tokens. Lengths are px. */
export type NodeAppearance = {
  width?: number | "hug" | "fill";
  height?: number | "hug" | "fill";
  minWidth?: number;
  minHeight?: number;
  maxWidth?: number | "fill";
  paddingTop?: number;
  paddingRight?: number;
  paddingBottom?: number;
  paddingLeft?: number;
  marginTop?: number;
  marginRight?: number;
  marginBottom?: number;
  marginLeft?: number;
  borderTopLeftRadius?: number;
  borderTopRightRadius?: number;
  borderBottomRightRadius?: number;
  borderBottomLeftRadius?: number;
  fontSize?: number;
  fontWeight?: number;
  /** Unitless multiplier. */
  lineHeight?: number;
  letterSpacing?: number;
  textAlign?: "left" | "center" | "right" | "justify";
  gap?: number;
  /** Six-digit hex or transparent; never arbitrary CSS. */
  background?: string;
  color?: string;
  borderColor?: string;
  borderWidth?: number;
  shadow?: "none" | "sm" | "md" | "lg";
  opacity?: number;
};
export type NodePart = "root" | "row" | "label" | "control" | "description" | "error";
export type NodeParts = Partial<Record<NodePart, NodeAppearance>>;
export type AppearanceProps = { appearance?: NodeAppearance };
export type AppearancePatch = { [K in keyof NodeAppearance]?: NodeAppearance[K] | null };
export type PartsPatch = Partial<Record<NodePart, AppearancePatch | null>>;
export type AppearanceField = {
  key: keyof NodeAppearance;
  label: string;
  group: "dimensions" | "padding" | "margin" | "radius" | "typography" | "layout" | "surface";
  type: "number" | "dimension" | "select" | "color";
  min?: number;
  max?: number;
  step?: number;
  options?: readonly string[];
};

/** Stable order is also the serialization/style order. No defaults are materialized. */
export const appearanceFields: readonly AppearanceField[] = [
  { key: "width", label: "Width", group: "dimensions", type: "dimension", min: 0, max: 10000, step: 1, options: ["hug", "fill"] },
  { key: "height", label: "Height", group: "dimensions", type: "dimension", min: 0, max: 10000, step: 1, options: ["hug", "fill"] },
  { key: "minWidth", label: "Min width", group: "dimensions", type: "number", min: 0, max: 10000, step: 1 },
  { key: "minHeight", label: "Min height", group: "dimensions", type: "number", min: 0, max: 10000, step: 1 },
  { key: "maxWidth", label: "Max width", group: "dimensions", type: "dimension", min: 0, max: 10000, step: 1, options: ["fill"] },
  ...(["Top", "Right", "Bottom", "Left"] as const).map((edge): AppearanceField => ({ key: `padding${edge}`, label: `Padding ${edge.toLowerCase()}`, group: "padding", type: "number", min: 0, max: 1000, step: 1 })),
  ...(["Top", "Right", "Bottom", "Left"] as const).map((edge): AppearanceField => ({ key: `margin${edge}`, label: `Margin ${edge.toLowerCase()}`, group: "margin", type: "number", min: -1000, max: 1000, step: 1 })),
  ...(["TopLeft", "TopRight", "BottomRight", "BottomLeft"] as const).map((corner): AppearanceField => ({ key: `border${corner}Radius`, label: `${corner.replace(/([a-z])([A-Z])/g, "$1 $2")} radius`, group: "radius", type: "number", min: 0, max: 1000, step: 1 })),
  { key: "fontSize", label: "Font size", group: "typography", type: "number", min: 1, max: 512, step: 1 },
  { key: "fontWeight", label: "Font weight", group: "typography", type: "number", min: 1, max: 1000, step: 1 },
  { key: "lineHeight", label: "Line height", group: "typography", type: "number", min: 0.1, max: 10, step: 0.05 },
  { key: "letterSpacing", label: "Letter spacing", group: "typography", type: "number", min: -100, max: 100, step: 0.1 },
  { key: "textAlign", label: "Text align", group: "typography", type: "select", options: ["left", "center", "right", "justify"] },
  { key: "gap", label: "Gap", group: "layout", type: "number", min: 0, max: 1000, step: 1 },
  { key: "background", label: "Background", group: "surface", type: "color", options: ["transparent"] },
  { key: "color", label: "Color", group: "surface", type: "color" },
  { key: "borderColor", label: "Border color", group: "surface", type: "color", options: ["transparent"] },
  { key: "borderWidth", label: "Border width", group: "surface", type: "number", min: 0, max: 100, step: 1 },
  { key: "shadow", label: "Shadow", group: "surface", type: "select", options: ["none", "sm", "md", "lg"] },
  { key: "opacity", label: "Opacity", group: "surface", type: "number", min: 0, max: 1, step: 0.05 },
];

export function appearanceRecord(value: unknown, path: string): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value) || ![Object.prototype, null].includes(Object.getPrototypeOf(value))) throw new Error(`${path}: expected plain object`);
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key !== "string" || !Object.getOwnPropertyDescriptor(value, key)?.enumerable || !Object.prototype.hasOwnProperty.call(Object.getOwnPropertyDescriptor(value, key), "value")) throw new Error(`${path}: expected serialized keys and values`);
  }
  return value as Record<string, unknown>;
}

export function parseAppearance(value: unknown, fields: readonly AppearanceField[] = appearanceFields, path = "appearance"): NodeAppearance {
  const raw = appearanceRecord(value, path);
  for (const key of Object.keys(raw)) if (!fields.some((field) => field.key === key)) throw new Error(`${path}: unknown or unsupported key ${key}`);
  const result: NodeAppearance = {};
  for (const field of fields) {
    if (!Object.prototype.hasOwnProperty.call(raw, field.key)) continue;
    const entry = raw[field.key];
    const option = typeof entry === "string" && field.options?.includes(entry);
    const numeric = typeof entry === "number" && Number.isFinite(entry) && entry >= field.min! && entry <= field.max! && (field.key !== "fontWeight" || Number.isInteger(entry));
    const valid = field.type === "color" ? option || (typeof entry === "string" && /^#[\da-fA-F]{6}$/.test(entry))
      : field.type === "select" ? option : field.type === "dimension" ? numeric || option : numeric;
    if (!valid) throw new Error(`${path}: invalid ${field.key}`);
    Object.assign(result, { [field.key]: entry });
  }
  return result;
}

/** Only explicit box geometry changes inline text flow; a color/font edit must not. */
export function hasAppearanceBox(appearance?: NodeAppearance): boolean {
  return !!appearance && appearanceFields.some((field) => ["dimensions", "padding", "margin"].includes(field.group) && appearance[field.key] !== undefined);
}

/** Converts only validated, allowlisted data; never forwards arbitrary style keys. */
export function appearanceToStyle(appearance?: NodeAppearance): CSSProperties | undefined {
  if (appearance === undefined) return undefined;
  const value = parseAppearance(appearance);
  if (!Object.keys(value).length) return undefined;
  const style: CSSProperties = { boxSizing: "border-box" };
  for (const [key, entry] of Object.entries(value)) {
    if (key === "shadow") style.boxShadow = entry === "none" ? "none" : `var(--ds-shadow-${entry})`;
    else if (key === "background") style.backgroundColor = entry as string;
    else Object.assign(style, { [key]: entry === "fill" ? "100%" : entry === "hug" ? key === "height" ? "auto" : "fit-content" : entry });
  }
  // Explicit geometry wins over size-preset minimums, but not a local minimum.
  if (value.height !== undefined && value.minHeight === undefined) style.minHeight = 0;
  if (value.borderWidth !== undefined) style.borderStyle = "solid";
  return style;
}

export function mergeAppearanceStyle(style: CSSProperties | undefined, appearance?: NodeAppearance): CSSProperties | undefined;
export function mergeAppearanceStyle<State>(style: CSSProperties | ((state: State) => CSSProperties | undefined) | undefined, appearance?: NodeAppearance): CSSProperties | ((state: State) => CSSProperties | undefined) | undefined;
export function mergeAppearanceStyle<State>(style: CSSProperties | ((state: State) => CSSProperties | undefined) | undefined, appearance?: NodeAppearance) {
  const local = appearanceToStyle(appearance);
  if (!local) return style;
  return typeof style === "function" ? (state: State) => ({ ...style(state), ...local }) : { ...style, ...local };
}

components/badge.tsx.content:
import type { ComponentProps, ReactNode } from "react";
import { cx } from "../cx";
import type { AppearanceProps } from "./appearance";
import { componentRecipeKey } from "./recipes";
import { componentRecipeMarkers, mergeRecipeStyle } from "./recipe-runtime";
import type { Radius, Size, Tone } from "./types";
import styles from "./components.module.css";

export type BadgeProps = ComponentProps<"span"> & AppearanceProps & {
  /** Fill style. Defaults to `outline`, which uses the badge component tokens. */
  variant?: "solid" | "subtle" | "outline";
  /** Semantic color role. Defaults to `neutral`. */
  tone?: Tone;
  /** Defaults to `md`. */
  size?: Size;
  /** Selects a shared global radius step. Defaults to `md`. */
  radius?: Radius;
  /** Shows a leading status dot. */
  dot?: boolean;
  /** Decorative icon before the label. */
  startIcon?: ReactNode;
};

export function Badge({
  variant = "outline",
  tone = "neutral",
  size = "md",
  radius,
  dot = false,
  startIcon,
  className,
  children,
  appearance,
  style,
  ...props
}: BadgeProps) {
  const recipe = componentRecipeKey("badge", { variant, size, tone });
  return (
    <span
      {...props}
      style={mergeRecipeStyle("badge", recipe, style, appearance)}
      {...componentRecipeMarkers("badge", "root")}
      data-component-recipe={recipe}
      className={cx(styles.badge, className)}
      data-variant={variant}
      data-tone={tone}
      data-size={size}
      data-radius={radius}
    >
      {dot && <span className={styles.badgeDot} aria-hidden="true" />}
      {startIcon && (
        <span className={styles.decorativeIcon} aria-hidden="true">{startIcon}</span>
      )}
      <span {...componentRecipeMarkers("badge", "text")} className={cx(styles.badgeContent, appearance?.textAlign && styles.alignedContent)}>{children}</span>
    </span>
  );
}

components/button.tsx.content:
import type { ReactNode } from "react";
import { Button as BaseButton } from "@base-ui/react/button";
import { cx } from "../cx";
import { Spinner } from "./spinner";
import type { AppearanceProps } from "./appearance";
import { componentRecipeKey } from "./recipes";
import { componentRecipeMarkers, mergeRecipeStyle } from "./recipe-runtime";
import type { Radius, Size } from "./types";
import styles from "./components.module.css";

type ButtonBaseProps = Omit<BaseButton.Props, "className"> & AppearanceProps & {
  /** Visual hierarchy and intent. Defaults to `primary`. */
  variant?: "primary" | "secondary" | "outline" | "ghost" | "destructive" | "link";
  /** Height, padding and font size from the shared size scale. Defaults to `md`. */
  size?: Size;
  /** Selects a shared global radius step. Defaults to `md`. */
  radius?: Radius;
  /** Shows a spinner and blocks activation while keeping the button focusable. */
  loading?: boolean;
  /** Stretches the button to the width of its container. */
  fullWidth?: boolean;
  /** Icon rendered before the label. Replaced by the spinner while loading. */
  startIcon?: ReactNode;
  /** Icon rendered after the label. */
  endIcon?: ReactNode;
  className?: string;
};

export type ButtonProps = ButtonBaseProps &
  (
    | { iconOnly?: false }
    /** Square button whose only child is an icon; an accessible name is required. */
    | { iconOnly: true; "aria-label": string }
  );

export function Button({
  variant = "primary",
  size = "md",
  radius,
  loading = false,
  fullWidth = false,
  iconOnly = false,
  disabled = false,
  startIcon,
  endIcon,
  className,
  children,
  appearance,
  style,
  ...props
}: ButtonProps) {
  const recipe = componentRecipeKey("button", { variant, size });
  return (
    <BaseButton
      {...props}
      style={mergeRecipeStyle("button", recipe, style, appearance)}
      {...componentRecipeMarkers("button", "root")}
      data-component-recipe={recipe}
      className={cx(styles.button, className)}
      disabled={disabled || loading}
      // Keep focus on the button when it enters the loading state after activation.
      focusableWhenDisabled={loading || props.focusableWhenDisabled}
      aria-busy={loading || undefined}
      data-variant={variant}
      data-size={size}
      data-radius={radius}
      data-loading={loading || undefined}
      data-icon-only={iconOnly || undefined}
      data-full-width={fullWidth || undefined}
    >
      {loading ? <Spinner /> : startIcon && (
              <span className={styles.decorativeIcon} aria-hidden="true">{startIcon}</span>
            )}
      {iconOnly && loading ? null : iconOnly ? children : <span {...componentRecipeMarkers("button", "text")} className={cx(styles.buttonContent, appearance?.textAlign && styles.alignedContent)}>{children}</span>}
      {!iconOnly && endIcon && (
              <span className={styles.decorativeIcon} aria-hidden="true">{endIcon}</span>
            )}
    </BaseButton>
  );
}

components/card.tsx.content:
import type { ComponentProps } from "react";
import { cx } from "../cx";
import { hasAppearanceBox, mergeAppearanceStyle, type AppearanceProps } from "./appearance";
import type { Radius, Size } from "./types";
import { componentRecipeKey } from "./recipes";
import { cardSlotRecipeStyle, componentRecipeMarkers, mergeRecipeStyle } from "./recipe-runtime";
import styles from "./components.module.css";

export type CardProps = ComponentProps<"article"> & AppearanceProps & {
  /** Surface treatment. Defaults to `outlined`, which uses the card component tokens. */
  variant?: "outlined" | "elevated" | "filled";
  /** Padding and gap density from the shared size scale. Defaults to `md`. */
  size?: Size;
  /** Selects a shared global radius step. Defaults to `md`. */
  radius?: Radius;
};

function CardRoot({
  variant = "outlined",
  size = "md",
  radius,
  className,
  appearance,
  style,
  ...props
}: CardProps) {
  const recipe = componentRecipeKey("card", { variant, size });
  return (
    <article
      {...props}
      style={mergeRecipeStyle("card", recipe, style, appearance)}
      {...componentRecipeMarkers("card", "root")}
      data-component-recipe={recipe}
      className={cx(styles.card, className)}
      data-variant={variant}
      data-size={size}
      data-radius={radius}
    />
  );
}

/** Decorative leading symbol. Hidden from assistive technology. */
function CardIcon({ className, appearance, style, ...props }: ComponentProps<"span"> & AppearanceProps) {
  return (
    <span
      aria-hidden="true"
      {...props}
      style={mergeAppearanceStyle(style, appearance)}
      {...componentRecipeMarkers("card", "icon")}
      className={cx(styles.cardIcon, className)}
    />
  );
}

/** Groups the title and description. */
function CardHeader({ className, appearance, style, ...props }: ComponentProps<"div"> & AppearanceProps) {
  return <div {...props} {...componentRecipeMarkers("card", "header")} style={mergeAppearanceStyle(style, appearance)} className={cx(styles.cardHeader, className)} />;
}

function CardTitle({ className, appearance, style, ...props }: ComponentProps<"strong"> & AppearanceProps) {
  return <strong {...props} {...componentRecipeMarkers("card", "title")} style={mergeAppearanceStyle(style, appearance)} data-appearance-box={hasAppearanceBox(appearance) || undefined} className={cx(styles.cardTitle, className)} />;
}

function CardDescription({ className, appearance, style, ...props }: ComponentProps<"p"> & AppearanceProps) {
  return <p {...props} {...componentRecipeMarkers("card", "description")} style={mergeAppearanceStyle(style, appearance)} className={cx(styles.cardDescription, className)} />;
}

function CardContent({ className, appearance, style, ...props }: ComponentProps<"div"> & AppearanceProps) {
  return <div {...props} {...componentRecipeMarkers("card", "content")} style={cardSlotRecipeStyle("content", style, appearance)} className={cx(styles.cardContent, className)} />;
}

/** Actions or metadata aligned at the end of the card. */
function CardFooter({ className, appearance, style, ...props }: ComponentProps<"div"> & AppearanceProps) {
  return <div {...props} {...componentRecipeMarkers("card", "footer")} style={cardSlotRecipeStyle("footer", style, appearance)} className={cx(styles.cardFooter, className)} />;
}

export const Card = Object.assign(CardRoot, {
  Icon: CardIcon,
  Header: CardHeader,
  Title: CardTitle,
  Description: CardDescription,
  Content: CardContent,
  Footer: CardFooter,
});

components/checkbox.tsx.content:
"use client";

import { Checkbox as BaseCheckbox } from "@base-ui/react/checkbox";
import { Field } from "@base-ui/react/field";
import { Icon } from "../icons";
import { FieldRoot, labelClassName, type FieldProps } from "./field";
import styles from "./components.module.css";
import { appearanceToStyle, mergeAppearanceStyle } from "./appearance";
import { componentRecipeMarkers } from "./recipe-runtime";

export type CheckboxProps = Omit<
  BaseCheckbox.Root.Props,
  "className" | "children"
> &
  FieldProps & {
    /** Side of the control the label sits on. Defaults to `end`. */
    labelPosition?: "start" | "end";
  };

export function Checkbox({
  label,
  hideLabel,
  description,
  error,
  errorPosition,
  errorIcon,
  appearance,
  parts,
  style,
  size,
  radius,
  className,
  labelPosition = "end",
  disabled,
  ...props
}: CheckboxProps) {
  return (
    <FieldRoot
      kind="choice"
      component="checkbox"
      pageOwner={props["data-page-node"]}
      size={size}
      radius={radius}
      disabled={disabled}
      description={description}
      error={error}
      errorPosition={errorPosition}
      errorIcon={errorIcon}
      parts={parts}
      className={className}
    >
      <Field.Label
        {...componentRecipeMarkers("checkbox", "row")}
        data-appearance-part="row"
        className={styles.choice}
        style={appearanceToStyle(parts?.row)}
        data-label-position={labelPosition}
      >
        <BaseCheckbox.Root
          {...props}
          {...componentRecipeMarkers("checkbox", "control")}
          data-appearance-part="control"
          disabled={disabled}
          className={styles.checkbox}
          style={mergeAppearanceStyle(style, appearance || parts?.control ? { ...appearance, ...parts?.control } : undefined)}
        >
          <BaseCheckbox.Indicator
            className={styles.indicator}
            render={(indicatorProps, state) => (
              <span {...indicatorProps}>
                <Icon name={state.indeterminate ? "minus" : "check"} />
              </span>
            )}
          />
        </BaseCheckbox.Root>
        <span {...componentRecipeMarkers("checkbox", "label")} data-appearance-part="label" data-hide-label={hideLabel || undefined} className={labelClassName(hideLabel)} style={hideLabel ? undefined : appearanceToStyle(parts?.label)}>
          {hideLabel && parts?.label ? <span style={appearanceToStyle(parts.label)}>{label}</span> : label}
        </span>
      </Field.Label>
    </FieldRoot>
  );
}

components/components.module.css.content:
/*
 * bambiui components.
 *
 * Visual values come from the design-system variables that `toCSSVariables()`
 * sets on the theme root: component tokens (`--{component}-{token}`) and global
 * roles (`--ds-*`). Interaction values (`--ds-state-*`, focus ring, size scale
 * factors) are defined on the same root, so every component hovers, presses,
 * focuses, disables and sizes the same way.
 *
 * Conventions: `data-variant`, `data-tone` and `data-size` carry the public API;
 * Base UI state attributes (`data-disabled`, `data-invalid`, `data-checked`, …)
 * carry interaction state. State is never encoded as a variant.
 */

/* Size scale ---------------------------------------------------------------- */

:is(.button, .field, .badge, .card)[data-size="sm"] {
  --size-scale: var(--ds-size-scale-sm);
  --size-height: var(--ds-control-height-sm);
}

:is(.button, .field, .badge, .card)[data-size="md"] {
  --size-scale: 1;
  --size-height: var(--ds-control-height-md);
}

:is(.button, .field, .badge, .card)[data-size="lg"] {
  --size-scale: var(--ds-size-scale-lg);
  --size-height: var(--ds-control-height-lg);
}

/* Shared control behavior --------------------------------------------------- */

.button:focus-visible,
.inputControl:has(:focus-visible),
.switch:focus-visible,
.checkbox:focus-visible {
  outline: var(--ds-focus-ring-width) solid var(--ds-primary-focus);
  outline-offset: var(--ds-focus-ring-offset);
}

.button[data-disabled]:not([data-loading]),
.field[data-disabled] {
  opacity: var(--ds-state-disabled-opacity);
  cursor: not-allowed;
}

.field[data-disabled] :is(.choice, .input) {
  cursor: not-allowed;
}

.spinner {
  animation: spin var(--ds-spinner-duration) linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(1turn);
  }
}

/* Radius scale opt-in; omitted props preserve legacy numeric component radius values. */
.button[data-radius="sm"], .field[data-radius="sm"] .inputControl, .field[data-radius="sm"] .checkbox { --part-radius: var(--ds-radius-sm); }
.button[data-radius="md"], .field[data-radius="md"] .inputControl, .field[data-radius="md"] .checkbox { --part-radius: var(--ds-radius-md); }
.button[data-radius="lg"], .field[data-radius="lg"] .inputControl, .field[data-radius="lg"] .checkbox { --part-radius: var(--ds-radius-lg); }
.badge[data-radius="sm"] { --part-radius: var(--ds-radius-sm); }
.badge[data-radius="md"] { --part-radius: var(--ds-radius-md); }
.badge[data-radius="lg"] { --part-radius: var(--ds-radius-lg); }
.card[data-radius="sm"] { --part-radius: var(--ds-radius-sm); }
.card[data-radius="md"] { --part-radius: var(--ds-radius-md); }
.card[data-radius="lg"] { --part-radius: var(--ds-radius-lg); }

/* Button -------------------------------------------------------------------- */

.button {
  --button-fill: var(--button-variant-primary-background);
  --button-ink: var(--button-variant-primary-foreground);
  --button-stroke: var(--button-variant-primary-border);
  --button-border-width: var(--button-variant-primary-border-width);
  --button-shadow: var(--button-variant-primary-shadow);
  --button-hover-fill: var(--button-variant-primary-hover-background);
  --button-active-fill: var(--button-variant-primary-active-background);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-height: var(--size-height);
