import { Field } from "@base-ui/react/field";
import { Switch as BaseSwitch } from "@base-ui/react/switch";
import { FieldRoot, labelClassName, type FieldProps } from "./field";
import styles from "./components.module.css";
import { appearanceToStyle, hasAppearanceBox, mergeAppearanceStyle } from "./appearance";
import { componentRecipeMarkers } from "./recipe-runtime";

export type SwitchProps = Omit<
  BaseSwitch.Root.Props,
  "className" | "children"
> &
  Omit<FieldProps, "radius"> & {
    /** Side of the control the label sits on. Defaults to `end`. */
    labelPosition?: "start" | "end";
  };

export function Switch({
  label,
  hideLabel,
  description,
  error,
  errorPosition,
  errorIcon,
  appearance,
  parts,
  style,
  size,
  className,
  labelPosition = "end",
  disabled,
  ...props
}: SwitchProps) {
  const control = appearance || parts?.control ? { ...appearance, ...parts?.control } : undefined;
  return (
    <FieldRoot
      kind="choice"
      component="switch"
      pageOwner={props["data-page-node"]}
      size={size}
      disabled={disabled}
      description={description}
      error={error}
      errorPosition={errorPosition}
      errorIcon={errorIcon}
      parts={parts}
      className={className}
    >
      <Field.Label
        {...componentRecipeMarkers("switch", "row")}
        data-appearance-part="row"
        className={styles.choice}
        style={appearanceToStyle(parts?.row)}
        data-label-position={labelPosition}
      >
        <BaseSwitch.Root
          {...props}
          {...componentRecipeMarkers("switch", "control")}
          data-appearance-part="control"
          disabled={disabled}
          className={styles.switch}
          style={mergeAppearanceStyle(style, control)}
          data-local-geometry={hasAppearanceBox(control) || control?.borderWidth !== undefined || undefined}
        >
          <BaseSwitch.Thumb className={styles.thumb} />
        </BaseSwitch.Root>
        <span {...componentRecipeMarkers("switch", "label")} data-appearance-part="label" data-hide-label={hideLabel || undefined} className={labelClassName(hideLabel)} style={hideLabel ? undefined : appearanceToStyle(parts?.label)}>
          {hideLabel && parts?.label ? <span style={appearanceToStyle(parts.label)}>{label}</span> : label}
        </span>
      </Field.Label>
    </FieldRoot>
  );
}

components/text.tsx.content:
import type { ComponentPropsWithoutRef } from "react";
import { cx } from "../cx";
import { hasAppearanceBox, type AppearanceProps } from "./appearance";
import { componentRecipeKey } from "./recipes";
import { componentRecipeMarkers, mergeRecipeStyle } from "./recipe-runtime";
import type { Size, Tone } from "./types";
import styles from "./components.module.css";

type TextElement = "h1" | "h2" | "h3" | "h4" | "h5" | "h6" | "p" | "span";
export type TextVariant = "heading" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6" | "paragraph" | "label" | "caption";

export type TextProps<T extends TextElement = "p"> = Omit<ComponentPropsWithoutRef<T>, "as" | "size"> & AppearanceProps & {
  /** Typography style, independent of the rendered element. Defaults to `paragraph`. */
  variant?: TextVariant;
  /** Defaults to `md`. */
  size?: Size;
  /** Semantic text color. Defaults to `neutral`. */
  tone?: Tone;
  /** Native element. Defaults to the matching heading for `h1`–`h6`, `h2` for `heading`, `p` for `paragraph`, and `span` otherwise. */
  as?: T;
};

export function Text<T extends TextElement = "p">({
  as,
  variant = "paragraph",
  size = "md",
  tone = "neutral",
  className,
  appearance,
  style,
  ...props
}: TextProps<T>) {
  const recipe = componentRecipeKey("text", { variant, size, tone });
  const Element: TextElement = as ?? (variant === "heading" ? "h2" : /^h[1-6]$/.test(variant) ? variant as TextElement : variant === "paragraph" ? "p" : "span");

  return (
    <Element
      {...props}
      style={mergeRecipeStyle("text", recipe, style, appearance)}
      {...componentRecipeMarkers("text", "root")}
      data-component-recipe={recipe}
      data-appearance-box={hasAppearanceBox(appearance) || undefined}
      className={cx(styles.text, className)}
      data-variant={variant}
      data-size={size}
      data-tone={tone}
    />
  );
}

components/types.ts.content:
/** Shared anatomy types also used by the pure System style/recipe models. */
export type SharedComponentId = "button" | "input" | "switch" | "checkbox" | "badge" | "card" | "text";
export type ComponentStylePart = "root" | "control" | "row" | "label" | "description" | "error" | "header" | "title" | "content" | "footer" | "icon";

/** Shared size scale. Maps to the `controlHeight{Sm,Md,Lg}` tokens. */
export type Size = "sm" | "md" | "lg";

/** Global radius scale. Resolves to the shared radiusSm/radius/radiusLg foundation tokens. */
export type Radius = "sm" | "md" | "lg";

/** Semantic color roles. Map to the global color tokens of the same name. */
export type Tone = "neutral" | "primary" | "success" | "warning" | "danger" | "info";

