.container {
  box-sizing: border-box;
  width: 100%;
  max-width: 72rem;
  margin-inline: auto;
  padding-inline: var(--ds-spacing-lg);
}

.container[data-max-width="narrow"] { max-width: 42rem; }
.container[data-max-width="full"] { max-width: none; padding-inline: 0; }

/* Container auto layout is opt-in; legacy block flow and margin collapse stay intact. */
.container[data-direction] {
  display: flex;
  flex-direction: column;
  gap: var(--ds-spacing-md);
  align-items: stretch;
  justify-content: flex-start;
}

.container[data-direction="row"] { flex-direction: row; }
.container[data-direction][data-gap="sm"] { gap: var(--ds-spacing-sm); }
.container[data-direction][data-gap="lg"] { gap: var(--ds-spacing-lg); }
.container[data-direction][data-align="start"] { align-items: flex-start; }
.container[data-direction][data-align="center"] { align-items: center; }
.container[data-direction][data-align="end"] { align-items: flex-end; }
.container[data-direction][data-justify="center"] { justify-content: center; }
.container[data-direction][data-justify="end"] { justify-content: flex-end; }
.container[data-direction][data-justify="between"] { justify-content: space-between; }
.container[data-direction][data-wrap] { flex-wrap: wrap; }

.stack {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: var(--ds-spacing-md);
}

.stack[data-direction="row"] { flex-direction: row; }
.stack[data-wrap] { flex-wrap: wrap; }
.stack[data-gap="sm"], .grid[data-gap="sm"] { gap: var(--ds-spacing-sm); }
.stack[data-gap="lg"], .grid[data-gap="lg"] { gap: var(--ds-spacing-lg); }
.stack[data-align="start"] { align-items: flex-start; }
.stack[data-align="center"] { align-items: center; }
.stack[data-align="end"] { align-items: flex-end; }
.stack[data-justify="center"] { justify-content: center; }
.stack[data-justify="end"] { justify-content: flex-end; }
.stack[data-justify="between"] { justify-content: space-between; }

.gridContainer {
  min-width: 0;
  container-type: inline-size;
}

.grid {
  display: grid;
  min-width: 0;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--ds-spacing-md);
}

.grid[data-columns="1"] { grid-template-columns: minmax(0, 1fr); }
.grid[data-columns="3"] { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.gridItem { min-width: 0; }
.gridItem[data-span="2"] { grid-column: span 2; }
.gridItem[data-span="3"] { grid-column: span 3; }
.grid[data-columns="1"] > .gridItem,
.grid[data-columns="2"] > .gridItem[data-span="3"] { grid-column: 1 / -1; }

@container (max-width: 32rem) {
  .grid[data-columns] { grid-template-columns: minmax(0, 1fr); }
  .grid[data-columns] > .gridItem { grid-column: 1 / -1; }
}
